import { test, expect } from "@playwright/test";

test("select an option", async ({ page }) => {
  await page.setContent('<label>Size<select><option value="s">Small</option><option value="l">Large</option></select></label>');
  await page.getByLabel("Size").selectOption("l");
  await expect(page.getByLabel("Size")).toHaveValue("l");
});
